import csv
import io
import json
import re
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "budget-ledger.html"
SCRIPT_ID = "app"
FEATURES = ["transactions", "balance", "categories", "monthly", "search", "sorting",
            "budgets", "recurring", "exporter", "importer", "chart", "persist"]

# The CSV the importer must read: written by Python's csv module, CRLF line ends,
# one field quoted because it holds a comma and a double quote.
IMPORT_ROWS = [
    ["2026-03-01", "Coffee beans", "Food", "-12.40"],
    ["2026-03-02", 'Dinner, "out"', "Food", "-48"],
    ["2026-03-05", "Tax refund", "Income", "250.75"],
]

DRIVER = r"""
const fs = require('fs');
const vm = require('vm');
const noop = () => {};
function el() {
  return {
    innerHTML: '', textContent: '', value: '', checked: false, style: {}, dataset: {},
    children: [], childNodes: [], parentNode: null,
    classList: { add: noop, remove: noop, toggle: noop, contains: () => false },
    addEventListener: noop, removeEventListener: noop, dispatchEvent: noop,
    appendChild: (x) => x, append: noop, prepend: noop, removeChild: noop,
    replaceChildren: noop, insertBefore: noop, remove: noop, setAttribute: noop,
    removeAttribute: noop, getAttribute: () => null, hasAttribute: () => false,
    focus: noop, blur: noop, click: noop, closest: () => null, matches: () => false,
    querySelector: () => el(), querySelectorAll: () => [], getElementsByTagName: () => [],
    getBoundingClientRect: () => ({ x: 0, y: 0, width: 0, height: 0, top: 0, left: 0, right: 0, bottom: 0 }),
  };
}
const bag = new Map();
const storage = {
  getItem: (k) => (bag.has(String(k)) ? bag.get(String(k)) : null),
  setItem: (k, v) => { bag.set(String(k), String(v)); },
  removeItem: (k) => { bag.delete(String(k)); },
  clear: () => bag.clear(),
  key: (i) => Array.from(bag.keys())[i] ?? null,
  get length() { return bag.size; },
};
Object.defineProperty(globalThis, 'localStorage', { value: storage, configurable: true, writable: true });
globalThis.document = Object.assign(el(), {
  getElementById: () => el(), createElement: () => el(), createElementNS: () => el(),
  createTextNode: (t) => ({ textContent: String(t) }), createDocumentFragment: () => el(),
  body: el(), head: el(), documentElement: el(), readyState: 'loading',
});
globalThis.window = globalThis;
globalThis.location = { hash: '', href: '', search: '' };
globalThis.history = { pushState: noop, replaceState: noop };
globalThis.requestAnimationFrame = () => 0;
globalThis.alert = noop; globalThis.confirm = () => true; globalThis.prompt = () => null;

const out = { app: false, features: {} };
try {
  vm.runInThisContext(fs.readFileSync('app.js', 'utf8'), { filename: 'app.js' });
} catch (e) {
  out.load_error = String((e && e.stack) || e).slice(0, 800);
}
const App = globalThis.App;
out.app = !!(App && App.features && typeof App.features === 'object');

const TX = [
  { id: 'a', date: '2026-01-05', description: 'Salary', category: 'Income', amount: 3000 },
  { id: 'b', date: '2026-01-07', description: 'Groceries at Market', category: 'Food', amount: -120.5 },
  { id: 'c', date: '2026-01-20', description: 'Rent', category: 'Housing', amount: -900 },
  { id: 'd', date: '2026-02-03', description: 'groceries again', category: 'Food', amount: -80 },
  { id: 'e', date: '2026-02-10', description: 'Bus pass', category: 'Transport', amount: -45.25 },
  { id: 'f', date: '2026-02-15', description: 'Freelance', category: 'Income', amount: 400 },
];
const ids = (list) => (list || []).map((t) => t.id);
const frozen = JSON.stringify(TX);

function feature(name, fn) {
  const r = { present: false, has_model: false, has_render: false };
  try {
    const f = App && App.features && App.features[name];
    r.present = !!f;
    if (f) {
      r.has_model = !!f.model && typeof f.model === 'object';
      r.has_render = typeof f.render === 'function';
      Object.assign(r, fn(f.model));
      r.mutated_input = JSON.stringify(TX) !== frozen;
    }
  } catch (e) {
    r.error = String((e && e.stack) || e).slice(0, 600);
  }
  out.features[name] = r;
}

feature('transactions', (m) => {
  const fresh = { date: '2026-03-01', description: 'Coffee', category: 'Food', amount: -3.5 };
  const one = m.add(TX, fresh);
  const two = m.add(one, { date: '2026-03-02', description: 'Tea', category: 'Food', amount: -2 });
  return {
    after_add: one.length, after_two: two.length, original: TX.length,
    ids_two: ids(two).map((i) => String(i)),
    new_items: two.slice(-2).map((t) => ({ description: t.description, amount: t.amount, has_id: t.id !== undefined && t.id !== null && t.id !== '' })),
    removed: ids(m.remove(TX, 'c')).map(String),
    valid_errors: m.validate({ date: '2026-03-01', description: 'x', category: 'Food', amount: -1 }),
    bad_errors: m.validate({ date: 'yesterday', description: '   ', category: 'Food', amount: 0 }),
  };
});

feature('balance', (m) => m.totals(TX));

feature('categories', (m) => ({ rows: m.byCategory(TX) }));

feature('monthly', (m) => ({
  months: m.months(TX),
  feb: ids(m.forMonth(TX, '2026-02')).map(String),
  none: ids(m.forMonth(TX, '2025-12')).map(String),
}));

feature('search', (m) => ({
  groc: ids(m.search(TX, 'GROC')).map(String),
  empty: ids(m.search(TX, '')).map(String),
  blank: ids(m.search(TX, '   ')).map(String),
  miss: ids(m.search(TX, 'zzz')).map(String),
}));

feature('sorting', (m) => ({
  amount_asc: ids(m.sortBy(TX, 'amount', 'asc')).map(String),
  date_desc: ids(m.sortBy(TX, 'date', 'desc')).map(String),
  desc_asc: (m.sortBy(TX, 'description', 'asc') || []).map((t) => t.description),
}));

feature('budgets', (m) => ({
  jan: m.status(TX, { Food: 150, Housing: 1000 }, '2026-01'),
  feb: m.status(TX, { Food: 150, Housing: 1000 }, '2026-02'),
  over: m.status(TX, { Food: 100 }, '2026-01'),
}));

feature('recurring', (m) => {
  const rule = { description: 'Gym', category: 'Health', amount: -30, day: 15, start: '2026-01-15' };
  const late = { description: 'Gym', category: 'Health', amount: -30, day: 15, start: '2026-03-15' };
  return {
    four: m.occurrences(rule, '2026-01-01', '2026-04-30'),
    three: (m.occurrences(rule, '2026-02-01', '2026-04-30') || []).map((o) => o.date),
    none: (m.occurrences(rule, '2026-01-01', '2026-01-14') || []).length,
    late: (m.occurrences(late, '2026-01-01', '2026-04-30') || []).map((o) => o.date),
  };
});

feature('exporter', (m) => ({
  csv: m.toCsv(TX.concat([{ id: 'g', date: '2026-02-20', description: 'Dinner, "out"', category: 'Food', amount: -48 }])),
}));

feature('importer', (m) => ({ rows: m.fromCsv(__CSV__) }));

feature('chart', (m) => ({ bars: m.bars(TX, 200) }));

feature('persist', (m) => {
  const before = m.load();
  const state = { transactions: TX, budgets: { Food: 150 }, recurring: [] };
  m.save(state);
  return { before, after: m.load(), stored: storage.length, raw_is_json: (() => {
    try { JSON.parse(storage.getItem(storage.key(0))); return true; } catch (e) { return false; }
  })() };
});

console.log(JSON.stringify(out));
"""


def node():
    return shutil.which("node") or shutil.which("node.exe")


def run_app(script):
    buf = io.StringIO()
    csv.writer(buf, lineterminator="\r\n").writerows([["date", "description", "category", "amount"]] + IMPORT_ROWS)
    driver = DRIVER.replace("__CSV__", json.dumps(buf.getvalue()))
    with tempfile.TemporaryDirectory() as tmp:
        d = Path(tmp)
        (d / "app.js").write_text(script, encoding="utf-8")
        (d / "driver.js").write_text(driver, encoding="utf-8")
        done = subprocess.run([node(), str(d / "driver.js")], capture_output=True, text=True,
                              timeout=60, cwd=d)
        if done.returncode != 0:
            raise AssertionError("app script failed in node: %s" % done.stderr[-800:])
        return json.loads(done.stdout.strip().splitlines()[-1])


def ids(rows):
    return [str(r) for r in (rows or [])]


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        m = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>(.*?)</script>' % SCRIPT_ID, cls.raw, re.S | re.I)
        cls.script = m.group(1) if m else None
        cls.data, cls.error = None, None
        if cls.script and node():
            try:
                cls.data = run_app(cls.script)
            except (AssertionError, ValueError) as exc:
                cls.error = str(exc)

    def feature(self, name):
        """The measured model of one feature, plus its panel in the page."""
        self.assertIsNotNone(self.script, 'no <script id="%s"> block in the page' % SCRIPT_ID)
        if node() is None:
            raise unittest.SkipTest("node is required to run the app script")
        self.assertIsNone(self.error, self.error)
        self.assertIsNone(self.data.get("load_error"), "app script threw while loading: %s" % self.data.get("load_error"))
        self.assertTrue(self.data.get("app"), "the app script must define window.App.features")
        self.assertRegex(self.raw, r'id=["\']panel-%s["\']' % name, "no <section id=\"panel-%s\"> in the page" % name)
        got = self.data["features"].get(name)
        self.assertTrue(got and got.get("present"), "App.features.%s is missing" % name)
        self.assertTrue(got.get("has_model"), "App.features.%s.model must be an object of pure functions" % name)
        self.assertTrue(got.get("has_render"), "App.features.%s.render must be a function" % name)
        self.assertIsNone(got.get("error"), "App.features.%s.model threw: %s" % (name, got.get("error")))
        self.assertFalse(got.get("mutated_input"), "App.features.%s.model mutated its input list" % name)
        return got

    # --- the page ---------------------------------------------------------
    def test_page_is_one_self_contained_html_file(self):
        self.assertRegex(self.raw[:400].lower(), r"<!doctype html")
        for pat, why in ((r'src\s*=\s*["\'](https?:)?//', "external src"),
                         (r'href\s*=\s*["\'](https?:)?//', "external href"),
                         (r"@import", "css @import"),
                         (r'url\(\s*["\']?(https?:)?//', "external url()"),
                         (r"\bfetch\s*\(", "network fetch"),
                         (r"XMLHttpRequest", "XHR")):
            self.assertIsNone(re.search(pat, self.raw, re.I), "page must be self-contained: found %s" % why)
        self.assertIsNotNone(self.script, 'no <script id="%s"> block' % SCRIPT_ID)
        tag = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>' % SCRIPT_ID, self.raw, re.I).group(0)
        self.assertNotIn("module", tag.lower(), "the app script must be a plain script, not type=module")
        self.assertRegex(self.raw, r"<nav\b", "the page needs a <nav> with the feature tabs")
        for name in FEATURES:
            self.assertRegex(self.raw, r'data-tab=["\']%s["\']' % name, "no tab for %s" % name)
            self.assertRegex(self.raw, r'id=["\']panel-%s["\']' % name, "no panel for %s" % name)

    def test_app_script_defines_every_feature(self):
        self.assertIsNotNone(self.script, 'no <script id="%s"> block' % SCRIPT_ID)
        if node() is None:
            raise unittest.SkipTest("node is required to run the app script")
        self.assertIsNone(self.error, self.error)
        self.assertIsNone(self.data.get("load_error"), "app script threw while loading: %s" % self.data.get("load_error"))
        self.assertTrue(self.data.get("app"), "the app script must define window.App.features")
        missing = [n for n in FEATURES if not (self.data["features"].get(n) or {}).get("present")]
        self.assertEqual(missing, [], "features missing from App.features: %s" % missing)

    # --- the twelve features, one test each --------------------------------
    def test_feature_transactions(self):
        got = self.feature("transactions")
        self.assertEqual(got["original"], 6, "add() must not change the list it was given")
        self.assertEqual(got["after_add"], 7)
        self.assertEqual(got["after_two"], 8)
        self.assertEqual(len(set(got["ids_two"])), 8, "every transaction needs a unique id")
        for item in got["new_items"]:
            self.assertTrue(item["has_id"], "a new transaction must be given an id")
        self.assertEqual(got["new_items"][0]["description"], "Coffee")
        self.assertAlmostEqual(got["new_items"][0]["amount"], -3.5, places=6)
        self.assertEqual(got["removed"], ["a", "b", "d", "e", "f"])
        self.assertEqual(got["valid_errors"], [], "a valid transaction has no errors")
        self.assertEqual(len(got["bad_errors"]), 3,
                         "bad date, blank description and zero amount are three errors, got %r" % (got["bad_errors"],))

    def test_feature_balance(self):
        got = self.feature("balance")
        self.assertAlmostEqual(got["income"], 3400, places=2)
        self.assertAlmostEqual(got["expense"], 1145.75, places=2)
        self.assertAlmostEqual(got["balance"], 2254.25, places=2)

    def test_feature_categories(self):
        rows = self.feature("categories")["rows"]
        self.assertEqual([r["category"] for r in rows], ["Housing", "Food", "Transport"],
                         "expense categories, largest first, income excluded")
        self.assertAlmostEqual(rows[0]["total"], 900, places=2)
        self.assertAlmostEqual(rows[1]["total"], 200.5, places=2)
        self.assertAlmostEqual(rows[2]["total"], 45.25, places=2)

    def test_feature_monthly(self):
        got = self.feature("monthly")
        self.assertEqual(got["months"], ["2026-01", "2026-02"])
        self.assertEqual(got["feb"], ["d", "e", "f"])
        self.assertEqual(got["none"], [])

    def test_feature_search(self):
        got = self.feature("search")
        self.assertEqual(got["groc"], ["b", "d"], "search is case-insensitive on the description")
        self.assertEqual(got["empty"], ["a", "b", "c", "d", "e", "f"], "an empty query keeps everything")
        self.assertEqual(got["blank"], ["a", "b", "c", "d", "e", "f"], "a blank query keeps everything")
        self.assertEqual(got["miss"], [])

    def test_feature_sorting(self):
        got = self.feature("sorting")
        self.assertEqual(got["amount_asc"], ["c", "b", "d", "e", "f", "a"])
        self.assertEqual(got["date_desc"], ["f", "e", "d", "c", "b", "a"])
        self.assertEqual([d.lower() for d in got["desc_asc"]],
                         ["bus pass", "freelance", "groceries again", "groceries at market", "rent", "salary"],
                         "description sort is case-insensitive")

    def test_feature_budgets(self):
        got = self.feature("budgets")
        jan = {r["category"]: r for r in got["jan"]}
        self.assertEqual(sorted(jan), ["Food", "Housing"])
        self.assertAlmostEqual(jan["Food"]["spent"], 120.5, places=2)
        self.assertAlmostEqual(jan["Food"]["remaining"], 29.5, places=2)
        self.assertFalse(jan["Food"]["over"])
        self.assertAlmostEqual(jan["Housing"]["spent"], 900, places=2)
        self.assertAlmostEqual(jan["Housing"]["limit"], 1000, places=2)
        feb = {r["category"]: r for r in got["feb"]}
        self.assertAlmostEqual(feb["Food"]["spent"], 80, places=2)
        self.assertAlmostEqual(feb["Housing"]["spent"], 0, places=2)
        over = {r["category"]: r for r in got["over"]}
        self.assertTrue(over["Food"]["over"], "spending 120.50 against a 100 limit is over budget")
        self.assertAlmostEqual(over["Food"]["remaining"], -20.5, places=2)

    def test_feature_recurring(self):
        got = self.feature("recurring")
        self.assertEqual([o["date"] for o in got["four"]],
                         ["2026-01-15", "2026-02-15", "2026-03-15", "2026-04-15"])
        for o in got["four"]:
            self.assertEqual(o["description"], "Gym")
            self.assertEqual(o["category"], "Health")
            self.assertAlmostEqual(o["amount"], -30, places=6)
        self.assertEqual(got["three"], ["2026-02-15", "2026-03-15", "2026-04-15"])
        self.assertEqual(got["none"], 0)
        self.assertEqual(got["late"], ["2026-03-15", "2026-04-15"], "nothing before the rule's start date")

    def test_feature_exporter(self):
        text = self.feature("exporter")["csv"]
        self.assertIsInstance(text, str)
        rows = list(csv.reader(io.StringIO(text)))
        rows = [r for r in rows if r]
        self.assertEqual([h.strip().lower() for h in rows[0]], ["date", "description", "category", "amount"])
        self.assertEqual(len(rows), 8, "header plus seven transactions")
        self.assertEqual(rows[1][:3], ["2026-01-05", "Salary", "Income"])
        self.assertAlmostEqual(float(rows[1][3]), 3000, places=2)
        self.assertEqual(rows[7][1], 'Dinner, "out"', "commas and quotes must survive CSV quoting")
        self.assertAlmostEqual(float(rows[7][3]), -48, places=2)

    def test_feature_importer(self):
        rows = self.feature("importer")["rows"]
        self.assertEqual(len(rows), 3, "three data rows after the header")
        self.assertEqual([r["date"] for r in rows], ["2026-03-01", "2026-03-02", "2026-03-05"])
        self.assertEqual(rows[1]["description"], 'Dinner, "out"')
        self.assertEqual([r["category"] for r in rows], ["Food", "Food", "Income"])
        for r, want in zip(rows, [-12.4, -48, 250.75]):
            self.assertIsInstance(r["amount"], (int, float), "amounts must be numbers, not strings")
            self.assertAlmostEqual(r["amount"], want, places=2)

    def test_feature_chart(self):
        bars = self.feature("chart")["bars"]
        byname = {b["category"]: b for b in bars}
        self.assertEqual(sorted(byname), ["Food", "Housing", "Transport"], "one bar per expense category")
        self.assertAlmostEqual(byname["Housing"]["width"], 200, delta=1, msg="the largest bar fills the width")
        self.assertAlmostEqual(byname["Food"]["width"], 200 * 200.5 / 900, delta=1)
        self.assertAlmostEqual(byname["Transport"]["width"], 200 * 45.25 / 900, delta=1)
        self.assertEqual([b["category"] for b in bars], ["Housing", "Food", "Transport"], "largest bar first")

    def test_feature_persist(self):
        got = self.feature("persist")
        self.assertIsNone(got["before"], "load() returns null when nothing was saved")
        self.assertGreaterEqual(got["stored"], 1, "save() must write to localStorage")
        self.assertTrue(got["raw_is_json"], "the saved value must be JSON")
        after = got["after"]
        self.assertEqual([t["id"] for t in after["transactions"]], ["a", "b", "c", "d", "e", "f"])
        self.assertEqual(after["budgets"], {"Food": 150})
        self.assertEqual(after["recurring"], [])


if __name__ == "__main__":
    unittest.main()
